-- ============================================================================
-- Guia do Vendedor — URLs oficiais das fontes.
--
-- Pesquisadas e depois submetidas a um verificador cético, que reabriu cada
-- página. Só entrou URL que alguém ABRIU e confirmou ser da organização certa.
-- O que não passou continua sem URL: a tela diz "URL a confirmar na revisão
-- técnica", e isso é melhor que um link que ninguém conferiu.
--
-- consultada_em = data em que a página foi aberta, não a data da obra.
-- ============================================================================

update public.guia_fontes set url = 'https://www.gov.br/agricultura/pt-br/assuntos/insumos-agropecuarios/insumos-pecuarios/alimentacao-animal/legislacao-alimentacao-animal', titulo = 'Legislação - Alimentação Animal', organizacao = 'Ministério da Agricultura e Pecuária (MAPA) — gov.br/agricultura', observacao = 'ABRI E CONFERI. Página institucional do MAPA no gov.br, subseção Insumos Agropecuários > Insumos Pecuários > Alimentação Animal. Descrição da própria página: ''Relação de normativos referentes à alimentação animal no Brasil''. Lista Lei 6.198/1974 (inspeção e fiscalização de produtos para alimentação animal), Lei 14.515/2022, Decreto 12.031/2024 (regulamenta a Lei 6.198/74 — norma vigente que rege registro/fiscalização), Decreto 12.502/2025, Decreto 12.126/2024, mais de 40 Instruções Normativas (ingredientes, aditivos, rotulagem, registro de produtos) e portarias, com PDF de cada norma. Escolhi esta em vez da página-mãe porque a tarefa pedia a de legislação específica quando existisse. PÁGINA-MÃE (hub), também aberta e confirmada, caso o card precise de contexto mais amplo (registro, SIPEAGRO, aditivos autorizados/proibidos, importação/exportação): https://www.gov.br/agricultura/pt-br/assuntos/insumos-agropecuarios/insumos-pecuarios/alimentacao-animal — título ''Produtos para Alimentação Animal''. DOIS PONTOS DE NOME/DOMÍNIO: (1) o órgão mudou de nome — era ''Ministério da Agricultura, Pecuária e Abastecimento'' e hoje se assina ''Ministério da Agricultura e Pecuária'', mas a sigla MAPA e o path /agricultura seguem valendo; (2) o domínio antigo www.agricultura.gov.br está descontinuado e migrou para www.gov.br/agricultura — se o guia tiver link legado em agricultura.gov.br, trocar. NÃO PREENCHI ''ano'': é página-índice viva, atualizada a cada norma nova; datar a página induziria erro. Se algum card citar exigência legal específica, o correto é citar a norma (ex.: Decreto 12.031/2024), não o ano da página.', consultada_em = date '2026-08-04' where chave = 'mapa-alimentacao-animal';
update public.guia_fontes set url = 'https://www.editoraufv.com.br/tabelas-brasileiras-para-aves-e-suinos/p', titulo = 'Tabelas Brasileiras para Aves e Suínos — Composição de Alimentos e Exigências Nutricionais', organizacao = 'Horacio Santiago Rostagno e Luiz Fernando Teixeira Albino (Depto. de Zootecnia, UFV) — página na loja da Editora UFV', edicao = '5ª edição', observacao = 'ABRI NO NAVEGADOR E LI A FICHA TÉCNICA: ''Tabelas Brasileiras para Aves e Suínos — Composição de Alimentos e Exigências Nutricionais - 5ª Edição''. Autores: Horacio Santiago Rostagno e Luiz Fernando Teixeira Albino. Ano 2024. 531 páginas, 16x23, ISBN 9788581792064. Trilha do site: Home > Ciências Agrárias > Zootecnia. ARMADILHA QUE EVITEI: a URL que o Google indexa (www.editoraufv.com.br/produto/tabelas-brasileiras-para-aves-e-suinos/1109046) está MORTA — abri e o site devolve ''ERROR 404 Não encontramos esta página''. A URL viva é a curta terminada em /p, que é a registrada aqui. Se ela cair, a busca interna da loja não acha o título (testei), então o caminho é navegar por Ciências Agrárias > Zootecnia. RESSALVA DE PROCEDÊNCIA, PARA O REVISOR DECIDIR: a ficha diz ''Editora: Produção Independente''. Ou seja, a 5ª edição é publicação independente dos próprios autores; a UFV entra como instituição dos autores (Depto. de Zootecnia) e a Editora UFV como canal de venda, não como selo editorial. Não achei página institucional da obra em domínio ufv.br: o que existe em ppg.ufv.br é uma notícia de 2017 sobre o lançamento da 4ª EDIÇÃO (abri e conferi — desatualizada, não serve). Por isso esta página da loja da própria UFV foi o melhor alvo estável e verificável encontrado. Risco conhecido: é página de produto, pode sair do ar se esgotar. Histórico das edições, para datar citação antiga: 1ª/2000, 2ª/2005, 3ª/2011, 4ª/2017, 5ª/2024 — QUALQUER número de conversão, exigência nutricional ou composição citada nos cards TEM de vir carimbada com a edição, porque os valores mudam entre edições.', ano = 2024, consultada_em = date '2026-08-04' where chave = 'rostagno-tabelas';
update public.guia_fontes set url = 'https://www.abcz.org.br/', titulo = 'Início | ABCZ', organizacao = 'Associação Brasileira dos Criadores de Zebu (ABCZ)', observacao = 'ABERTO E CONFIRMADO via WebFetch. Home institucional real, título ''Início | ABCZ''. Menu confirmado: A ABCZ / Produtos e Serviços (Área Técnica, Registro Genealógico/SRGRZ, PRODUZ) / PMGZ / Notícias e Revistas / Feiras e Eventos (ExpoZebu, ExpoGenética, ExpoLeite) / Fale Conosco. Sede Uberaba/MG (Praça Vicentino Rodrigues da Cunha, 110), fundada 1934 como Sociedade Rural do Triângulo Mineiro. PÁGINA DE RAÇAS TAMBÉM ABERTA E CONFIRMADA: https://www.abcz.org.br/a-abcz/racas-zebuinas — lista Brahman, Cangaian, Gir, Guzerá, Indubrasil, Nelore/Nelore Mocho, Punganur, Sindi e Tabapuã, com página própria por raça no padrão /a-abcz/racas-zebuinas/raca/{id}/{nome} (ex.: .../raca/5/gir, .../raca/8/nelore---nelore-mocho, .../raca/4/guzera — URLs vistas em índice, não abertas uma a uma). NÃO EXISTE página autônoma de ''padrão racial'' na ABCZ: a página de raças é descritiva (adaptação, produção) e não traz o padrão formal. Os padrões raciais vivem dentro do regulamento do SRGRZ (Registro Genealógico), cuja seção institucional é https://www.abcz.org.br/produtos-e-servicos/area-tecnica/registro-genealogico — indexada mas NÃO aberta por mim, portanto não confirmada. Por isso registrei a home (institucional, estável) e não uma subpágina. edicao/ano = null: site institucional de atualização contínua, sem edição ou ano de publicação; esses campos só fazem sentido para manual de linhagem.', consultada_em = date '2026-08-04' where chave = 'abcz';
update public.guia_fontes set url = 'https://www.girolando.com.br/area-tecnica/cruzamentos', titulo = 'Cruzamentos — Associação Brasileira dos Criadores de Girolando', organizacao = 'Associação Brasileira dos Criadores de Girolando', observacao = 'ABERTO E CONFIRMADO, mas só via navegador (Brain Bridge/CDP): girolando.com.br devolve HTTP 403 para WebFetch (bloqueio de bot). Li o DOM renderizado. ESCOLHA DA URL: o enunciado pede preferir padrão racial OU graus de sangue; existem AS DUAS páginas e eu abri as duas. Registrei /area-tecnica/cruzamentos porque é a que realmente resolve o card do Girolando — ela enumera as composições raciais aceitas, provando que a raça NÃO fecha num único grau de sangue. Composições lidas na própria página (29 opções, seletor Pai x Mãe): HOLANDÊS puro; GIR puro; 5/32; 7/32; 9/32; 11/32; 13/32; 1/4 HOL+3/4 GIR; 5/16 HOL+11/16 GIR; 3/8 HOL+5/8 GIR; 7/16; 15/32; 1/2 HOL+1/2 GIR; 17/32; 9/16; 19/32; 5/8 HOL+3/8 GIR; 21/32; 11/16 HOL+5/16 GIR; 23/32; 3/4 HOL+1/4 GIR; 25/32; 13/16; 27/32; 7/8 HOL+1/8 GIR; 29/32; 15/16 HOL+1/16 GIR; 23/64 HOL+41/64 GIR; e PS = PURO SINTÉTICO. A ALTERNATIVA https://www.girolando.com.br/area-tecnica/padrao-racial TAMBÉM FOI ABERTA E CONFIRMADA, mas tem conteúdo mínimo: só o link ''Nomenclatura Exterior e Padrão Racial da Raça Girolando'' para download. Esse download sai por https://www.girolando.com.br/baixar.php?arquivo=608 — endpoint com ID numérico, instável, NÃO usar como fonte (e não abri o PDF). Home https://www.girolando.com.br/ também aberta e confirmada; rodapé traz Rua Orlando Vieira do Nascimento, 74, Vila São Cristóvão, CEP 38040-280, Uberaba/MG, tel (34) 3331-6032, © 2026. NÃO CONFIRMADO POR MIM (veio só de snippet de busca, tratar como não verificado): o padrão de formação 5/8 HOL + 3/8 GIR definido pelo MAPA em 1989, e a mudança de nome para ''Associação Brasileira dos Criadores de Girolando'' pela Portaria 79 de 01/02/1996. edicao/ano = null: página web dinâmica, sem edição; o PDF de padrão racial não declara edição nem ano na página que o linka.', consultada_em = date '2026-08-04' where chave = 'girolando';
update public.guia_fontes set url = 'https://canchim.com.br/', titulo = 'Homepage - Canchim', organizacao = 'Associação Brasileira de Criadores de Canchim (ABCCAN)', observacao = 'ABERTO E CONFIRMADO via WebFetch. Título real ''Homepage - Canchim''. ATENÇÃO AO DOMÍNIO: é canchim.com.br, NÃO existe abccan.com.br/.org.br confirmado — a sigla ABCCAN é da entidade, o domínio é o nome da raça. Menu confirmado: ABCCAN (/abccan/) / CRIADORES (/abccan-2/associados/) / RAÇA CANCHIM (/raca-canchim/) / PCAD (/pcad/) / NOTÍCIAS (/noticias/) / GALERIA DE FOTOS (/fotos-gerais/). PÁGINA DA RAÇA TAMBÉM ABERTA E CONFIRMADA: https://canchim.com.br/raca-canchim/ (título ''Raça Canchim - Canchim'') — traz a composição racial textualmente: ''A junção do 3/8 Nelore e 5/8 Charolês fez do touro Canchim um touro adaptado para as condições climáticas do Brasil''. Tem subseção ''Formação Raça''. NÃO EXISTE página separada chamada ''padrão racial'' na ABCCAN — a página /raca-canchim/ é o mais próximo disso e é a que o guia deve citar para composição 5/8 Charolês + 3/8 Nelore. Registrei a home por ser a institucional estável, mas para o card use /raca-canchim/. ATENÇÃO AO NOME: o site e as fontes usam ''Associação Brasileira de Criadores de Canchim'' (SEM o ''dos''). NÃO CONFIRMADO POR MIM (só snippet de busca): fundação em 11/11/1971 como ''Associação Brasileira de Criadores de Bovinos da Raça Canchim'' e o registro nº 25 no MAPA pela Portaria 20 de 25/09/1972; sede no Parque Fernando Costa. Também não abri /abccan-2/nossa-historia/. edicao/ano = null: site institucional, sem edição/ano.', consultada_em = date '2026-08-04' where chave = 'abccan';
update public.guia_fontes set url = 'https://angus.org.br/', titulo = 'Angus.Org – Associação Brasileira de Angus', organizacao = 'Associação Brasileira de Angus (ABA)', observacao = 'ABERTO E CONFIRMADO via WebFetch (home + /quem-somos/ + /registro-genealogico/ + /downloads/). CORREÇÃO DE SIGLA — IMPORTANTE: a chave está como ''abcb-angus'', mas NÃO encontrei nenhuma entidade ou sigla ''ABCB'' ligada ao Angus no Brasil. O nome oficial no próprio site é ''Associação Brasileira de Angus'' e a sigla usada é ABA. Sugiro renomear a chave para ''aba-angus'' ou ''angus'' no catálogo, senão o card cita uma sigla que não existe. Dados confirmados em https://angus.org.br/quem-somos/: fundada em 1963 (movimento nascido em Uruguaiana/RS como ''Angus Brasil''), sede em Largo Visconde do Cairú, 12 – conj. 901 – Centro – Porto Alegre/RS, CEP 90030-110. Menu confirmado: Associação / Angus / Angus Market / Ultrablack / Carne Angus / Eventos / Notícias / Contato. RESSALVA CRÍTICA PARA O GUIA, confirmada em https://angus.org.br/registro-genealogico/: a ABA NÃO executa o registro genealógico — todo o registro do Angus no Brasil é feito pela Associação Nacional de Criadores Herd-Book Collares (ANC), sediada em Pelotas/RS, site herdbook.org.br. Se o card falar em registro/certificação de Angus, a fonte correta é a Herd-Book Collares, não a ABA. PADRÃO RACIAL: existe a página estável https://angus.org.br/manual-de-padrao-racial/ (sob o menu Carne Angus) — ela RESOLVE (não é 404), mas o que consegui ler foi só navegação/rodapé, o conteúdo parece ser um PDF embutido, então NÃO confirmo o conteúdo do manual. O PDF solto aparece em /wp-content/uploads/2022/06/manual-padrao-racial-angus-br-central-final.pdf — NÃO abri e NÃO recomendo citar (PDF de upload, caminho instável). Nenhuma edição ou ano é declarado para o manual em nenhuma das páginas que abri; por isso edicao/ano = null. Se o guia precisar citar número do manual, é preciso abrir o PDF e extrair edição/ano antes de usar. Página /ultrablack/ indexada (Ultrablack = 80% Angus + 20% zebu, por snippet) mas NÃO aberta por mim.', consultada_em = date '2026-08-04' where chave = 'angus-aba';
update public.guia_fontes set url = 'https://www.cobbgenetics.com/resource/management-guides', titulo = 'Cobb Learning Center — Management Guides (Broiler Management Guide + Cobb500 Broiler Performance and Nutrition Supplement)', organizacao = 'Cobb-Vantress, Inc. (marca comercial Cobb Genetics)', edicao = 'Broiler Management Guide, revisão 2021-09; Cobb500 Broiler Performance and Nutrition Supplement, revisão 2022-01', observacao = 'ABRI a pagina e ela lista, com data de revisao ao lado de cada documento: Broiler Management Guide (2021-09), Cobb500 Broiler Performance and Nutrition Supplement (2022-01), Breeder (2020-12), Hatchery (2020-07), Processing (2026-01), Vaccination (2025-07). MUDANCA DE DOMINIO: https://www.cobb-vantress.com/resource/management-guides responde HTTP 301 para https://www.cobbgenetics.com/resource/management-guides — a empresa continua sendo Cobb-Vantress, mas a marca/site virou Cobb Genetics. Registrei o dominio novo. A pagina https://www.cobbgenetics.com/resources tambem abre e e o hub mais amplo, caso prefiram. ano=2022 refere-se ao suplemento Cobb500, que e de onde saem os numeros de conversao alimentar e peso; o manual de manejo em si e de 2021.', ano = 2022, consultada_em = date '2026-08-04' where chave = 'manual-cobb';
update public.guia_fontes set url = 'https://aviagen.com/pt/tech-center', titulo = 'Aviagen Info Center / Centro Tecnico — biblioteca de documentos (Manual de Manejo de Frangos de Corte Ross, Ross Broiler Pocket Guide)', organizacao = 'Aviagen Group (Ross e marca da Aviagen)', edicao = 'Ross Broiler Management Handbook — versao interativa vigente (a pagina NAO exibe o ano); Broiler Performance Objectives 2022 para Ross 308 / 308 AP / 708', observacao = 'ATENCAO NA URL: https://aviagen.com/tech-center NAO abre a biblioteca — cai num seletor de regiao. So funciona com prefixo de regiao. Abri e confirmei DUAS: https://aviagen.com/pt/tech-center (portugues, lista ''Manual de Manejo de Frangos de Corte Ross'' e ''Manual de Matrizes Ross 2023'') e https://aviagen.com/eu/tech-center (ingles, lista ''Ross Broiler Handbook — New & Interactive'' e ''Ross Broiler Pocket Guide''). Registrei a PT por ser publico brasileiro; a EU e mais completa se precisarem do ingles. ANO NAO CONFIRMADO: nenhum dos dois cards mostra ano. Indicios fortes, mas nao verificados na capa: o PDF oficial em https://aviagen.com/assets/Tech_Center/Ross_Broiler/Aviagen-ROSS-Broiler-Handbook-EN.pdf aparece indexado com o titulo ''Management Handbook BROILER 2025'', e os objetivos de desempenho vigentes estao em https://aviagen.com/assets/Tech_Center/Ross_Broiler/RossxRoss308-BroilerPerformanceObjectives2022-EN.pdf (arquivo existe no dominio oficial, baixei os bytes). NAO consegui ler a capa de nenhum dos dois: o handbook passa de 10 MB e estoura o limite do fetch, e os PDFs de objetivos nao renderizaram texto. Logo, deixei ano=null em vez de chutar. Se alguem precisar citar conversao alimentar Ross 308, a edicao a citar e ''Broiler Performance Objectives 2022'' — mas convem abrir a capa do PDF para carimbar o ano antes de publicar.', consultada_em = date '2026-08-04' where chave = 'manual-ross';
update public.guia_fontes set url = 'https://www.hyline.com/literature', titulo = 'Hy-Line — Literature (hub de manuais e padroes de desempenho por linhagem: W-36, W-80, Brown, Silver Brown, Sonia/Gray, Pink)', organizacao = 'Hy-Line International', observacao = 'ABRI e confirmei o hub /literature, que da acesso a literatura das 6 linhagens, incluindo Brown e W-36. CUIDADO: a URL https://www.hyline.com/varieties/management-guides (que parece obvia) responde 404, e https://www.hyline.com/varieties/hy-line-brown tambem 404 — o caminho correto e /varieties/brown e /varieties/w-36. Tambem abri e confirmei as sub-paginas de download: https://www.hyline.com/literature/brown (Brown Commercial Layers conventional e alternative, Brown Max, Brown Max Pro, com versao em portugues) e https://www.hyline.com/literature/W-36 (Commercial Management Guide, Parent Stock Guide, Performance Summary, tambem com versao em portugues). EDICAO/ANO NAO CONFIRMADOS: a Hy-Line nao numera edicao nem exibe ano nas paginas — o proprio texto dela diz que os guias ''sao atualizados periodicamente''. Unico indicio: o PDF de padroes da Brown (BRN STD ENG.pdf) traz metadado de modificacao em 05/2026, mas isso e metadado do arquivo, nao edicao declarada, entao nao registrei como ano. Se precisarem carimbar ano, o caminho e abrir o PDF e ver o codigo de rodape.', consultada_em = date '2026-08-04' where chave = 'manual-hyline';
update public.guia_fontes set url = 'https://www.isa-poultry.com/en/product/isa-brown/', titulo = 'ISA Brown — pagina oficial do produto com downloads (product guide e management guide, versoes cage/EU/North America/S.E. Asia)', organizacao = 'ISA — Hendrix Genetics', edicao = 'Codigos de edicao dos documentos: L6230-1 (ISA Brown EU CS product guide, cage) e L4230-1-NA (ISA Brown CS management guide, versao North America)', observacao = 'ABRI e confirmei: a pagina do produto lista 9 PDFs baixaveis hospedados no proprio dominio isa-poultry.com, entre eles ''ISA Brown EU CS cage housing guide English'' (/documents/1399/ISA_Brown_EU_CS_product_guide_cage_EN_L6230-1.pdf) e ''ISA Brown cs management guide - North American version'' (/documents/302/ISA_Brown_cs_management_guide_North_America_L4230-1-NA_LR-web.pdf). CUIDADO COM URL: https://www.isa-poultry.com/en/products/isa-brown/ (com ''s'' em products) da 404 — o caminho correto e /en/product/isa-brown/. ANO NAO CONFIRMADO: a ISA nao publica ano de edicao, apenas o codigo de documento (L6230-1, L4230-1-NA), que e o que serve de versionamento — registrei esses codigos em ''edicao''. NOTA DE ORGANIZACAO: a ISA e marca da Hendrix Genetics; existe ainda o site regional hendrix-isa.com (mercado EUA) e o portal layinghens.hendrix-genetics.com, mas o dominio institucional da marca e isa-poultry.com, que foi o que registrei. EVITEI de proposito os PDFs que circulam em sites de revenda (frabopoultry.com) e no Scribd.', consultada_em = date '2026-08-04' where chave = 'manual-isa';
update public.guia_fontes set url = 'https://lohmann-breeders.com/download-resources/', titulo = 'Lohmann Breeders — Download & Resources (Management Guides por linhagem, cage housing e alternative housing)', organizacao = 'Lohmann Breeders GmbH', edicao = 'Management Guide Cage Housing por linhagem (LB_MG_Cage_LB-Classic_EN.pdf e LB_MG_Cage_LSL-Classic_EN.pdf, sem versao no arquivo); suplementos de Alternative Housing em versao V01-21 (06/2021)', observacao = 'ABRI e confirmei a pagina de downloads oficial, que organiza por Management Guide, Leaflets, Field Data Results, Production Charts e Publications, em varios idiomas (EN, ESP, GER, ARB, FRA, RU, CN). Confirmei os hrefs reais dos PDFs no proprio dominio: Brown-Classic cage = /files/downloads/MG/Cage/LB_MG_Cage_LB-Classic_EN.pdf; LSL-Classic cage = /files/downloads/MG/Cage/LB_MG_Cage_LSL-Classic_EN.pdf; e os suplementos de alojamento alternativo com versao explicita V01-21 datada 06.21. A pagina https://lohmann-breeders.com/management-guide/ tambem abre, mas e so um hub de navegacao sem os links diretos — por isso registrei /download-resources/. ANO NAO CONFIRMADO para o guia de gaiola: o nome do arquivo nao traz versao e a pagina nao exibe data; so os suplementos alternativos trazem V01-21 (2021). MUDANCA DE NOME: a empresa se chamava ''Lohmann Tierzucht GmbH'' e passou a ''Lohmann Breeders GmbH'' (grupo EW) — material antigo circula com o nome velho. CUIDADO: lohmanngb.co.uk e distribuidor no Reino Unido, nao a genetica; nao usar como fonte.', consultada_em = date '2026-08-04' where chave = 'manual-lohmann';
update public.guia_fontes set observacao = 'DOCUMENTO INTERNO DA BRANORTE — não tem URL pública e não deve receber link. Não busquei na web de propósito: qualquer resultado externo seria revenda, marketplace ou material de terceiro, e apontar o card do vendedor para isso seria pior do que não ter link. Sugestão para o card: exibir ''Catálogo interno Branorte'' sem hyperlink, ou apontar para o caminho interno (catálogo/tabela de preços da Branorte) se o guia suportar referência não-clicável. Se um dia a Branorte publicar catálogo em página própria do site institucional, aí vira URL confirmável.' where chave = 'branorte-catalogo';
update public.guia_fontes set observacao = 'DOCUMENTO INTERNO DA BRANORTE (acervo/base técnica de engenharia) — não tem URL pública e não deve receber link. Mesmo tratamento do branorte-catalogo: referência interna, sem hyperlink. Não inventei nem procurei substituto externo, porque dado de engenharia de equipamento próprio não existe em fonte pública confiável e um link de terceiro daria falsa autoridade a especificação que é da casa.' where chave = 'branorte-engenharia';
update public.guia_fontes set observacao = 'URL CANDIDATA, NÃO CONFIRMADA: https://www.embrapa.br/suinos-e-aves — NAO confirmei ao vivo. O portal www.embrapa.br esta FORA DO AR agora: ECONNREFUSED em 200.202.168.147:443 tanto via WebFetch quanto num Chrome real (a aba mostrou error page, sem body). Testei https, http e sem www — todos falharam. Nao e bloqueio do meu lado: outro host da Embrapa (www.bdpa.cnptia.embrapa.br) abriu normalmente na mesma sessao, entao a queda e especifica do portal institucional. O que EU confirmei: abri o snapshot do Internet Archive de 2025-12-09 dessa URL exata e o title veio ''Embrapa Suínos e Aves - Portal Embrapa'' — ou seja, a URL e mesmo a pagina da unidade e nao foi inventada. Endereco Concordia/SC (Rodovia BR-153, km 110, Distrito de Tamandua) apareceu em resultado de busca do proprio embrapa.br, mas nao abri a pagina de contato pra conferir. FALTA: reabrir https://www.embrapa.br/suinos-e-aves quando o portal voltar e so entao marcar confirmada=true. Campos ano/edicao ficam null de proposito: e pagina institucional de unidade, nao publicacao com edicao.' where chave = 'embrapa-suinos-aves';
update public.guia_fontes set observacao = 'URL CANDIDATA, NÃO CONFIRMADA: https://www.embrapa.br/gado-de-corte — NAO confirmei ao vivo — mesma queda do portal www.embrapa.br descrita na chave embrapa-suinos-aves (ECONNREFUSED 200.202.168.147:443 no WebFetch e error page no Chrome real). O que EU confirmei: abri o snapshot do Internet Archive de 2026-01-01 dessa URL exata e o title veio ''Embrapa Gado de Corte - Portal Embrapa''. Portanto a URL e a pagina da unidade, nao e chute. NAO verifiquei a localizacao Campo Grande/MS por fonte propria — isso veio do enunciado da tarefa, nao de pagina que eu tenha aberto. FALTA: reabrir https://www.embrapa.br/gado-de-corte ao vivo e conferir o endereco na aba de contato antes de marcar confirmada=true. ano/edicao null: pagina institucional de unidade, sem edicao.' where chave = 'embrapa-gado-corte';
update public.guia_fontes set observacao = 'URL CANDIDATA, NÃO CONFIRMADA: https://www.embrapa.br/gado-de-leite — NAO confirmei ao vivo — mesma queda do portal www.embrapa.br (ECONNREFUSED 200.202.168.147:443; Chrome real devolveu error page). O que EU confirmei: abri o snapshot do Internet Archive de 2025-12-31 dessa URL exata e o title veio ''Embrapa Gado de Leite - Portal Embrapa''. URL verificada, nao inventada. NAO verifiquei por fonte propria a localizacao Juiz de Fora/MG — veio do enunciado. FALTA: reabrir https://www.embrapa.br/gado-de-leite ao vivo antes de marcar confirmada=true. ano/edicao null: pagina institucional de unidade.' where chave = 'embrapa-gado-leite';
