update public.guia_fontes set observacao = 'URL CANDIDATA, NÃO CONFIRMADA: https://www.embrapa.br/semiarido — NAO confirmei ao vivo — mesma queda do portal www.embrapa.br (ECONNREFUSED 200.202.168.147:443; error page no Chrome real). Essa foi a mais trabalhosa: os snapshots de 2026-01-01 do Internet Archive devolveram ''503 Service Unavailable'' duas vezes seguidas. Voltei e abri o snapshot de 2025-01-03 dessa URL exata, e o title veio ''Embrapa Semiárido - Portal Embrapa''. Slug confirmado sem acento e sem hifen: ''semiarido''. NAO verifiquei por fonte propria a localizacao Petrolina/PE — veio do enunciado. FALTA: reabrir https://www.embrapa.br/semiarido ao vivo antes de marcar confirmada=true. ano/edicao null: pagina institucional de unidade.' where chave = 'embrapa-semiarido';
